#!/usr/bin/env python3
"""Install groups+feed UX slice onto the live droplet tree."""
import gzip, base64, json, shutil
from pathlib import Path
from datetime import datetime, timezone

BLOB = """"""
DATA = json.loads(gzip.decompress(base64.b64decode(BLOB)))
stamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ")
fail = []
ROOT = Path("/opt/liquidgov")

def once(name, text, old, new):
    n = text.count(old)
    print(name, n)
    if n == 0:
        if new and text.count(new) >= 1:
            print("  already")
            return text
        fail.append(name)
        return text
    if n != 1:
        fail.append(name + " count=" + str(n))
        return text
    return text.replace(old, new, 1)

files = {
    "hpp": ROOT / "libs/liquidgov_file_store/include/liquidgov/platform/file_store.hpp",
    "cpp": ROOT / "libs/liquidgov_file_store/src/file_store.cpp",
    "http": ROOT / "src/http_server.cpp",
}
for key, path in files.items():
    if not path.exists():
        raise SystemExit("missing " + str(path))
    shutil.copy2(path, str(path) + ".bak-gf-" + stamp)

texts = {k: p.read_text() for k, p in files.items()}
for item in DATA["hpp"]:
    texts["hpp"] = once("hpp:" + item["name"], texts["hpp"], item["old"], item["new"])
for item in DATA["cpp"]:
    texts["cpp"] = once("cpp:" + item["name"], texts["cpp"], item["old"], item["new"])
for item in DATA["http"]:
    texts["http"] = once("http:" + item["name"], texts["http"], item["old"], item["new"])
if fail:
    print("STOP", ", ".join(fail))
    print("NEED_BUILD 0")
    raise SystemExit(1)
for k, p in files.items():
    p.write_text(texts[k])
    print("wrote", p)
print("ok bak-gf-" + stamp)
print("NEED_BUILD 1")
